def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find full separator rows and columns (color 4).
    sep_rows = [r for r in range(h) if all(x == 4 for x in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 4 for r in range(h))]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_ranges = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_ranges = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    out = [row[:] for row in grid]
    source = None
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges:
            if any(grid[r][c] != 9 for r in range(r0, r1) for c in range(c0, c1)):
                source = (r0, r1, c0, c1)
                break
        if source:
            break

    if source:
        r0, r1, c0, c1 = source
        pattern = [row[c0:c1] for row in grid[r0:r1]]
        for a, b in row_ranges:
            for x, y in col_ranges:
                if (a, b, x, y) == source:
                    continue
                for i, r in enumerate(range(a, b)):
                    for j, c in enumerate(range(x, y)):
                        out[r][c] = pattern[i][j]

    return out
